// build/bundle.js — Concatenates src/*.js into a single css-neon.js
//
// Usage: node build/bundle.js
//
// Resolves ES import graph from src/index.js, strips internal import/export
// statements, and emits a self-contained css-neon.js at the repo root.

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SRC = path.join(ROOT, 'src');
const OUT = path.join(ROOT, 'css-neon.js');

// ---- resolve import graph (depth-first, post-order) ----
function resolveGraph(entryFile) {
  const order = [];
  const seen = new Set();

  function visit(filePath) {
    if (seen.has(filePath)) return;
    seen.add(filePath);
    const dir = path.dirname(filePath);
    const src = fs.readFileSync(filePath, 'utf8');
    for (const m of src.matchAll(/import\s+\{[^}]+\}\s+from\s+['"]\.\/([^'"]+)['"];?/g)) {
      const dep = path.join(dir, m[1].endsWith('.js') ? m[1] : m[1] + '.js');
      if (fs.existsSync(dep)) visit(dep);
    }
    order.push(filePath);
  }

  visit(entryFile);
  return order;
}

// ---- strip internal imports & exports, keep entry export ----
function cleanSource(filePath, isEntry) {
  let src = fs.readFileSync(filePath, 'utf8');

  // Strip local import lines
  src = src.replace(/import\s+\{[^}]+\}\s+from\s+['"]\.\/[^'"]+['"];?\s*/g, '');

  if (isEntry) {
    // entry: strip internal exports but keep the public export line
    // We handle this by keeping the whole file content (including export { ... })
    // but removing any export that looks like an internal re-export
  } else {
    // non-entry: strip ALL export statements
    src = src.replace(/export\s+\{[^}]+\};?/g, '');
    src = src.replace(/export\s+(default\s+)?/g, '');
  }

  // Collapse multiple blank lines
  src = src.replace(/\n{3,}/g, '\n\n').trim();

  return src;
}

// ---- main ----
function main() {
  const entry = path.join(SRC, 'index.js');
  const order = resolveGraph(entry);

  // Build header
  const lines = [
    '// css-neon — Neon light Web Component',
    '// Generated by build/bundle.js on ' + new Date().toISOString().slice(0, 10),
    '//',
    '// Usage:  <script type="module" src="css-neon.js"></script>',
    '//   or:   import { NeonLight, define } from "./css-neon.js";',
    '',
  ];

  for (const filePath of order) {
    const rel = path.relative(SRC, filePath).replace(/\\/g, '/');
    const isEntry = filePath === entry;
    let code = cleanSource(filePath, isEntry);
    lines.push(`/* ===== src/${rel} ===== */`);
    lines.push(code);
    lines.push('');
  }

  const output = lines.join('\n');
  fs.writeFileSync(OUT, output);
  console.log(`✓  Built ${path.relative(ROOT, OUT)}  (${(output.length / 1024).toFixed(1)} KB)`);
  console.log(`   ${order.length} modules: ${order.map(f => path.relative(SRC, f).replace(/\\/g, '/')).join(' → ')}`);
}

main();
